use axum::{extract::Path, http::StatusCode, routing::get, Router};
use std::fs;
use std::path::PathBuf;

async fn download(Path(filename): Path<String>) -> Result<String, (StatusCode, String)> {
    let base = PathBuf::from("files");
    let path = base.join(&filename);
    match fs::read_to_string(&path) {
        Ok(contents) => Ok(contents),
        Err(_) => Err((StatusCode::NOT_FOUND, "not found".to_string())),
    }
}

#[tokio::main]
async fn main() {
    let app = Router::new().route("/download/*filename", get(download));
    let listener = tokio::net::TcpListener::bind("0.0.0.0:8046").await.unwrap();
    axum::serve(listener, app).await.unwrap();
}

